DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Spyrath Studio</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}*{box-sizing:border-box}body{margin:0;background:#090b10;color:#f6f7fb}header{padding:24px 32px;border-bottom:1px solid #242936;background:#10131a;position:sticky;top:0;z-index:5}.brand{display:flex;align-items:center;justify-content:space-between;gap:16px}.brand h1{margin:0;font-size:25px}.sub,.muted{color:#929cad}.shell{max-width:1240px;margin:auto;padding:28px 24px 64px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:12px}.toolbar-actions,.actions{display:flex;gap:9px;flex-wrap:wrap}button,.button{border:0;border-radius:9px;padding:10px 14px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block;font-size:13px}.primary{background:#f1f4f8;color:#11151d}.secondary{background:#232937;color:#eef1f7;border:1px solid #343c4d}.danger{background:#3a2024;color:#ffb5bd;border:1px solid #643039}button:disabled{opacity:.5;cursor:not-allowed}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:18px}.card{background:#141821;border:1px solid #282e3b;border-radius:15px;padding:20px;box-shadow:0 10px 30px #0003}.row{display:flex;justify-content:space-between;gap:12px;align-items:center}.title{font-size:19px;font-weight:780}.status{font-size:12px;text-transform:uppercase;letter-spacing:.08em;padding:5px 8px;border-radius:99px;background:#222836;color:#b7c0cf}.progress-head{display:flex;justify-content:space-between;font-size:13px;margin-top:16px}.progress{height:10px;border-radius:99px;overflow:hidden;background:#262c38;margin:7px 0 15px}.bar{height:100%;background:#e9edf4;transition:width .35s ease}.chunk{background:#10141c;border:1px solid #262d3a;border-radius:10px;padding:11px 12px;margin:0 0 12px}.chunk strong{font-size:14px}.stage{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #202531;font-size:13px}.stage:last-child{border:0}.ok{color:#87d39c}.bad{color:#ff9696}.run{color:#f2cb7d}.error{color:#ffaaaa;font-size:13px;margin-top:12px;white-space:pre-wrap}.runtime{font-size:12px;color:#9ba5b6;margin:12px 0}.preview{display:grid;grid-template-columns:86px 1fr;gap:13px;align-items:center;margin:14px 0}.avatar{width:86px;height:86px;object-fit:cover;border-radius:11px;background:#0d1016;border:1px solid #2b3240}.empty{text-align:center;color:#8994a6;padding:48px}.modal-backdrop{position:fixed;inset:0;background:#000b;display:grid;place-items:center;padding:20px;z-index:20}.modal{width:min(700px,100%);max-height:92vh;overflow:auto;background:#141821;border:1px solid #313848;border-radius:16px;padding:22px}.modal h2{margin:0 0 6px}.hint{color:#939eaf;font-size:13px;line-height:1.5}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.full{grid-column:1/-1}label{display:block;color:#aab3c3;font-size:13px;margin-bottom:6px}input,select{width:100%;border:1px solid #343c4d;background:#0f131a;color:#f4f6fa;padding:11px;border-radius:9px}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.video-backdrop{position:fixed;inset:0;background:#000d;display:grid;place-items:center;padding:24px;z-index:30}.video-panel{width:min(1000px,100%)}video{width:100%;max-height:78vh;background:#000;border-radius:12px}.video-close{display:flex;justify-content:flex-end;margin-bottom:8px}@media(max-width:640px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.toolbar{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}}
</style></head><body>
<header><div class="brand"><div><h1>Spyrath Studio</h1><div class="sub">AI presenter production workspace</div></div><div id="runtimeSummary" class="muted"></div></div></header>
<main class="shell"><div class="toolbar"><div><strong>Projects</strong><div class="muted" style="font-size:12px;margin-top:4px">Production status updates automatically.</div></div><div class="toolbar-actions"><button class="secondary" onclick="refresh()">Refresh</button><button class="primary" onclick="openNewProject()">+ New Project</button></div></div><div id="projects" class="grid"></div><div id="empty" class="empty" hidden>No projects yet. Create your first presenter project.</div></main>
<div id="newProjectModal" class="modal-backdrop" hidden><div class="modal"><div class="row"><div><h2>New Project</h2><p class="hint">Upload your manuscript, voice reference and presenter image. Assets are stored with the project before production starts.</p></div><button class="secondary" onclick="closeNewProject()">✕</button></div><form id="projectForm" onsubmit="createProject(event)"><div class="form-grid"><div><label>Project ID</label><input name="project_id" required pattern="[A-Za-z0-9._-]+" placeholder="ml-book"></div><div><label>Project title</label><input name="title" required placeholder="Machine Learning for Beginners"></div><div class="full"><label>Manuscript (.txt or .md)</label><input name="manuscript" type="file" accept=".txt,.md,.markdown,text/plain,text/markdown" required></div><div><label>Voice sample</label><input name="voice_reference" type="file" accept="audio/*,.wav,.mp3,.m4a,.flac,.ogg" required></div><div><label>Presenter image</label><input name="presenter_image" type="file" accept="image/*,.png,.jpg,.jpeg,.webp" required></div><div><label>Language</label><select name="language"><option value="en">English</option></select></div></div><div id="formError" class="error"></div><div class="modal-actions"><button type="button" class="secondary" onclick="closeNewProject()">Cancel</button><button id="createButton" class="primary">Create Project</button></div></form></div></div>
<div id="videoModal" class="video-backdrop" hidden><div class="video-panel"><div class="video-close"><button class="secondary" onclick="closeVideo()">Close ✕</button></div><video id="player" controls></video></div></div>
<script>
const labels={narration:'Narration',audio_preparation:'Audio Preparation',presenter_video:'Presenter Generation',final_export:'Final Video'},marks={completed:'✓ Complete',running:'● Running',failed:'! Failed',pending:'○ Pending'};
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])); const js=v=>String(v).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
function cls(s){return s==='completed'?'ok':s==='failed'?'bad':s==='running'?'run':'muted'}
function elapsed(job){if(!job||!job.started_at)return '';const start=new Date(job.started_at),end=job.finished_at?new Date(job.finished_at):new Date();const sec=Math.max(0,Math.floor((end-start)/1000));const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${h}h ${m}m`:(m?`${m}m ${s}s`:`${s}s`)}
async function action(id,name){const r=await fetch(`/api/projects/${encodeURIComponent(id)}/${name}`,{method:'POST'});if(!r.ok){const b=await r.json().catch(()=>({detail:'Request failed'}));alert(b.detail||'Request failed')}setTimeout(refresh,250)}
function card(p){const stages=Object.entries(p.stages).map(([k,v])=>`<div class="stage"><span>${labels[k]||esc(k)}</span><span class="${cls(v.status)}">${marks[v.status]||esc(v.status)}</span></div>`).join('');const pp=p.presenter_progress||{completed:0,total:0,remaining:0};const chunk=pp.total?`<div class="chunk"><div class="row"><strong>Presenter chunks</strong><strong>${pp.completed} / ${pp.total}</strong></div><div class="progress" style="margin:8px 0 4px"><div class="bar" style="width:${Math.round(pp.completed/pp.total*100)}%"></div></div><span class="muted" style="font-size:12px">${pp.remaining} remaining</span></div>`:'';const job=p.runtime_job;const runtime=job?`<div class="runtime">Job: ${esc(job.status)} · attempt ${job.attempts}/${job.max_attempts}${job.started_at?' · '+elapsed(job):''}</div>`:'';const resume=p.status==='failed'||p.status==='partial';const label=p.running?'Running…':resume?'Resume Production':p.status==='completed'?'Run Again':'Start Production';const act=resume?'resume':'run';const final=p.final_path?`<button class="secondary" onclick="playVideo('${js(p.project_id)}')">▶ Preview</button><a class="button secondary" href="/api/projects/${encodeURIComponent(p.project_id)}/download">Download</a>`:'';return `<section class="card"><div class="row"><div><div class="title">${esc(p.title)}</div><div class="muted" style="font-size:12px;margin-top:3px">${esc(p.project_id)}</div></div><div class="status">${esc(p.status)}</div></div><div class="preview"><img class="avatar" src="/api/projects/${encodeURIComponent(p.project_id)}/media/presenter" onerror="this.style.visibility='hidden'"><div><div class="muted" style="font-size:12px">Presenter asset</div><a class="button secondary" style="margin-top:8px" href="/api/projects/${encodeURIComponent(p.project_id)}/media/voice">Voice sample</a></div></div><div class="progress-head"><span>Overall production</span><strong>${p.progress_percent}%</strong></div><div class="progress"><div class="bar" style="width:${p.progress_percent}%"></div></div>${chunk}${stages}${runtime}${p.last_error?`<div class="error">${esc(p.last_error)}</div>`:''}${job&&job.error&&!p.last_error?`<div class="error">${esc(job.error)}</div>`:''}<div class="actions"><button class="primary" ${p.running?'disabled':''} onclick="action('${js(p.project_id)}','${act}')">${label}</button>${final}</div></section>`}
async function refresh(){try{const r=await fetch('/api/projects'),d=await r.json();document.getElementById('projects').innerHTML=d.projects.map(card).join('');document.getElementById('empty').hidden=d.projects.length>0;const active=d.projects.filter(p=>p.running).length;document.getElementById('runtimeSummary').textContent=active?`${active} production job${active===1?'':'s'} active`:'Runtime ready'}catch(e){document.getElementById('runtimeSummary').textContent='Unable to reach runtime'}}
function openNewProject(){newProjectModal.hidden=false}function closeNewProject(){newProjectModal.hidden=true;formError.textContent=''}
async function createProject(e){e.preventDefault();const b=createButton;b.disabled=true;b.textContent='Creating…';formError.textContent='';try{const r=await fetch('/api/projects/upload',{method:'POST',body:new FormData(e.target)}),x=await r.json().catch(()=>({detail:'Unable to create project'}));if(!r.ok)throw new Error(x.detail);e.target.reset();closeNewProject();await refresh()}catch(x){formError.textContent=x.message}finally{b.disabled=false;b.textContent='Create Project'}}
function playVideo(id){player.src=`/api/projects/${encodeURIComponent(id)}/video`;videoModal.hidden=false;player.play().catch(()=>{})}function closeVideo(){player.pause();player.removeAttribute('src');player.load();videoModal.hidden=true}
refresh();setInterval(refresh,2000);
</script></body></html>'''
